import sys

class WordDictionaryBrute:
    def __init__(self):
        self.words = []
    def addWord(self, word):
        self.words.append(word)
    def search(self, word):
        for w in self.words:
            if len(w) != len(word):
                continue
            ok = True
            for a, b in zip(w, word):
                if b != '.' and a != b:
                    ok = False
                    break
            if ok:
                return True
        return False

if __name__ == '__main__':
