import sys

class Node:
    __slots__ = ('children', 'is_end')
    def __init__(self):
        self.children = {}
        self.is_end = False

class WordDictionaryTrie:
    def __init__(self):
        self.root = Node()
    def addWord(self, word):
        cur = self.root
        for ch in word:
            if ch not in cur.children:
                cur.children[ch] = Node()
            cur = cur.children[ch]
        cur.is_end = True
    def search(self, word):
        def dfs(node, i):
            if i == len(word):
                return node.is_end
            ch = word[i]
            if ch == '.':
                for nxt in node.children.values():
                    if dfs(nxt, i + 1):
                        return True
                return False
            if ch in node.children:
                return dfs(node.children[ch], i + 1)
            return False
        return dfs(self.root, 0)

